CREATE OR REPLACE FUNCTION public.assembly_lifecycle_validate_order()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM assembly_order_records WHERE id = NEW.order_id AND source = 'ozon') THEN
        RAISE EXCEPTION 'Lifecycle events require a real Ozon order' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.assembly_validate_disassembly_return_reversal()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF current_setting('transaction_isolation')='repeatable read' THEN
 RAISE EXCEPTION 'Disassembly ledger writes require READ COMMITTED or SERIALIZABLE' USING ERRCODE='0A000'; END IF;
 PERFORM 1 FROM assembly_disassembly_items i JOIN assembly_disassembly_returns r ON r.item_id=i.id
 WHERE r.id=NEW.return_id FOR UPDATE OF i;
 IF NOT FOUND THEN
 RAISE EXCEPTION 'Reversal must reference an existing physical return' USING ERRCODE='23503';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.assembly_validate_warehouse_operation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM assembly_order_positions p JOIN assembly_order_versions v ON v.id=p.version_id
 WHERE p.id=NEW.order_position_id AND v.order_id=NEW.order_id AND p.warehouse_product_id=NEW.product_id) THEN
  RAISE EXCEPTION 'Warehouse operation does not match order position' USING ERRCODE='23514';
 END IF;
 IF NEW.kind='undo_pick' AND NOT EXISTS(SELECT 1 FROM assembly_warehouse_operations original
 WHERE original.id=NEW.reverses_operation_id AND original.kind='pick' AND original.order_id=NEW.order_id
 AND original.order_position_id=NEW.order_position_id AND original.cell_id=NEW.cell_id AND original.product_id=NEW.product_id) THEN
  RAISE EXCEPTION 'Undo must match its original pick' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.receiving_advance_pending_revision()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'DELETE' THEN
        UPDATE receiving_sessions SET pending_revision = pending_revision + 1 WHERE id = OLD.session_id;
    ELSE
        UPDATE receiving_sessions SET pending_revision = pending_revision + 1 WHERE id = NEW.session_id;
        IF TG_OP = 'UPDATE' AND OLD.session_id <> NEW.session_id THEN
            UPDATE receiving_sessions SET pending_revision = pending_revision + 1 WHERE id = OLD.session_id;
        END IF;
    END IF;
    RETURN NULL;
END;
$function$
